\url{https://arxiv.org/abs/gr-qc/9306020}.
\item[S5] Ames--Andreasson--Rinne, recent Vlasov censorship study; reference in the saved dated catalogue literature review.
\url{https://doi.org/10.1103/PhysRevD.108.064054}.
\end{itemize}
\label{end:30001361}

